// Some portions generated by Codex
const { test, expect } = require('@playwright/test');
const path = require('node:path');
const { pathToFileURL } = require('node:url');
const root = path.resolve(__dirname, '../..');
const output = path.resolve(__dirname, '../test-results/find-field-fixture');

test.beforeAll(async () => {
    const { build } = await import(pathToFileURL(path.join(root, 'tools/workbench/node_modules/vite/dist/node/index.js')).href);
    await build({configFile:false, root:path.join(root, 'tools/workbench'),
        resolve:{alias:{react:path.join(root,'tools/workbench/node_modules/react'), 'react-dom':path.join(root,'tools/workbench/node_modules/react-dom')}},
        build:{outDir:output, emptyOutDir:false, lib:{entry:path.join(root,'e2e/fixtures/graph-find/main.tsx'), name:'FindFieldFixture', formats:['iife'], fileName:()=> 'fixture.js'}}});
});

test.beforeEach(async ({ page }) => {
    await page.setContent('<div id="root"></div>');
    await page.addScriptTag({path:path.join(output,'fixture.js')});
});

test('large and unknown repositories require the separate action, never bare Enter', async ({ page }) => {
    const input = page.getByRole('combobox');
    await input.fill('Bob');
    await expect(page.getByText('No matches in the loaded graph')).toBeVisible();
    await input.press('Enter');
    await expect(page.locator('output')).toHaveText('[]');
    await expect(page.getByText('No matches in the loaded graph')).toBeVisible();
    await page.getByRole('button', {name:'Search entire repository',exact:true}).click();
    await expect(page.locator('output')).toHaveText('["search:Bob"]');
    await page.getByRole('button', {name:'Unknown',exact:true}).click();
    await input.fill('Carol');
    await expect(page.getByText('No matches in the loaded graph')).toBeVisible();
    await input.press('Enter');
    await expect(page.locator('output')).toHaveText('["search:Bob"]');
});

test('local matches stay instant and small stores retain Enter fallback', async ({ page }) => {
    const input = page.getByRole('combobox');
    await input.fill('Alice');
    await expect(page.getByRole('option', {name: /Alice/})).toBeVisible();
    await input.press('Enter');
    await expect(page.locator('output')).toHaveText('["reveal:urn:alice"]');
    await page.getByRole('button', {name:'Small',exact:true}).click();
    await input.fill('Bob');
    await expect(page.getByText('No matches in the loaded graph')).toBeVisible();
    await input.press('Enter');
    await expect(page.locator('output')).toHaveText('["reveal:urn:alice","search:Bob"]');
});

test('exact IRI lookup remains explicit and keyboard accessible on large repositories', async ({ page }) => {
    const input = page.getByRole('combobox');
    await input.fill('https://example.org/bob');
    await expect(page.getByText('No matches in the loaded graph')).toBeVisible();
    await input.press('Enter');
    await expect(page.locator('output')).toHaveText('["search:https://example.org/bob"]');
    await input.fill('Carol');
    await expect(page.getByText('No matches in the loaded graph')).toBeVisible();
    await input.press('Tab');
    await expect(page.getByRole('button', {name:'Search entire repository',exact:true})).toBeFocused();
    await page.keyboard.press('Enter');
    await expect(page.locator('output')).toHaveText('["search:https://example.org/bob","search:Carol"]');
});

test('busy searches cannot be repeated and editing does not trigger new searches', async ({ page }) => {
    await page.getByRole('button', {name:'Toggle busy',exact:true}).click();
    await page.getByRole('combobox').fill('Bob');
    await expect(page.getByRole('button', {name:'Search entire repository',exact:true})).toBeDisabled();
    await page.getByRole('combobox').press('Enter');
    await expect(page.locator('output')).toHaveText('[]');
});
